    entries=txt.split('\n\n')
    for e in entries:
        def grab(key):
            m=re.search(r'^'+re.escape(key)+r' ((?:".*"\n?)+)', e, re.M)
            if not m: return None
            return ''.join(re.findall(r'"(.*)"', m.group(1)))
        mid=grab('msgid'); 
        if not mid or '%1%' not in mid and '%2%' not in mid: continue
        mpl=grab('msgid_plural')
        ph=lambda s:set(re.findall(r'%\d+%',s))
        need=ph(mid)|(ph(mpl) if mpl else set())
        strs=[]
        if mpl:
            for n in range(6):
                s=grab(f'msgstr[{n}]')
                if s is not None: strs.append((n,s))
        else:
            s=grab('msgstr'); strs=[('',s)]
        for n,s in strs:
            if not s: continue
            # boost::format throws if args > placeholders (too_many_args) — args count = max placeholder in source
            if ph(s)!=need:
                bad.append((f,n,mid[:70],sorted(ph(s)),sorted(need)))
